<script setup>
import {marinaFilterOptions} from '../../data/marinaFilters.js'
import { computed,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { useQuasar } from 'quasar'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import DataFilters from './DataFilters.vue'
import {assessOutput,mergeReportingAssessments,reportingAssessmentMetadata} from '../../data/reportingRequirements.js'
import {assessOperationalOutput} from '../operations/reportRequirements.js'
import { outputCatalogue,buildOutput } from '../../data/catalogue.js'
import { downloadCSV,downloadXLSX,downloadGeoJSON,printReport } from '../../lib/exports.js'
import { buildMAICSections,buildSpotSections,selectReportRevision } from './reportLogic.js'
const store=useDemo(),route=useRoute(),q=useQuasar(),search=ref(''),group=ref('All'),asOf=ref(new Date().toISOString().slice(0,10)),eventId=ref(''),previewJob=ref(null),snapshotOpen=ref(false),busy=ref(false),error=ref(''),template=ref('Demonstration v1'),note=ref('')
const workingCopyAccepted=ref(false)
const history=computed(()=>route.path==='/admin/exports'),builder=computed(()=>!!route.params.outputId),output=computed(()=>outputCatalogue.find(o=>o.id===route.params.outputId))
const selection=computed({get:()=>store.state.selection,set:v=>{store.state.selection=v;store.persist()}})
const filtered=computed(()=>store.selectEvents(selection.value)),documentOutput=computed(()=>['O15','O16','O17','O18'].includes(output.value?.id))
const contextEvent=computed(()=>route.query.eventId?store.getEvent(String(route.query.eventId)):null)
const contextExcluded=computed(()=>documentOutput.value&&contextEvent.value&&!filtered.value.some(event=>event.id===contextEvent.value.id))
const eventChoices=computed(()=>{const events=contextEvent.value&&!filtered.value.some(event=>event.id===contextEvent.value.id)?[contextEvent.value,...filtered.value]:filtered.value;return events.map(event=>({label:`${event.ref} · ${event.type}`,value:event.id}))})
function reportPath(id){return {path:`/admin/reports/build/${id}`,query:['O15','O16','O17','O18'].includes(id)&&contextEvent.value?{eventId:contextEvent.value.id}:{}}}
watch([()=>route.params.outputId,()=>route.query.eventId],([,id])=>{eventId.value=id&&store.getEvent(String(id))?String(id):''},{immediate:true})
const population=computed(()=>documentOutput.value?(eventId.value?filtered.value.filter(e=>e.id===eventId.value):[]):filtered.value)
const documentRevisions=computed(()=>{if(!documentOutput.value)return[];const type={O16:'1B',O17:'2',O18:'3B'}[output.value.id]||'spot';return population.value.map(event=>{const report=store.state.reports.filter(r=>r.eventId===event.id&&r.type===type&&(!asOf.value||!r.date||r.date<=asOf.value)).sort((a,b)=>(Number(b.revision)||0)-(Number(a.revision)||0))[0];return selectReportRevision({event,report,evidenceRecords:store.state.evidence})})})
const outputPopulation=computed(()=>output.value?.id==='O15'?documentRevisions.value.map(item=>item.event):population.value)
const rows=computed(()=>output.value?buildOutput(output.value.id,outputPopulation.value,{cases:store.state.cases,reports:['O16','O17','O18'].includes(output.value.id)?documentRevisions.value.map(item=>item.report).filter(Boolean):store.state.reports,imports:store.visibleRecords('imports')},{...selection.value,asOf:asOf.value}):[])
const reportingAssessment=computed(()=>mergeReportingAssessments(['O16','O17','O18'].includes(output.value?.id)?{items:[]}:assessOutput(output.value?.id,outputPopulation.value),assessOperationalOutput(output.value?.id,outputPopulation.value,{cases:store.visibleRecords('cases'),reports:store.visibleRecords('reports'),asOf:asOf.value})))
watch(()=>[output.value?.id,eventId.value,JSON.stringify(selection.value),JSON.stringify(reportingAssessment.value.unresolved.map(item=>item.key))],()=>workingCopyAccepted.value=false)
const columns=computed(()=>[...new Set(rows.value.flatMap(row=>Object.keys(row)))].map(field=>({name:field,label:field,field:r=>r[field] == null || r[field]===''?'Unknown':typeof r[field]==='object'?JSON.stringify(r[field]):r[field],align:'left',sortable:true})))
const groups=computed(()=>['All',...new Set(outputCatalogue.map(o=>o.group))])
const titles={O01:'Annual incident register',O02:'Monthly accident summary',O03:'Accidents by area of responsibility',O04:'Accidents by homeport',O05:'Involved vessels by service',O06:'Accidents by seriousness',O07:'Vessel hull, size and classification',O08:'Enforcement case outcomes',O09:'SCO summary by office',O10:'SCO and case register',O11:'Casualty and vessel consequences',O12:'Vessel and company summary by seriousness',O13:'MAIC reports received',O14:'Compare reporting years',O15:'Spot report',O16:'Form 1B · Initial investigation report',O17:'Form 2 · Progress report',O18:'Form 3B · Final investigation report',O19:'Overseas crew and passenger register',O20:'Map and event locations',O21:'Incident charts and supporting tables',O22:'Source reconciliation and missing information'}
const reportTitle=item=>item?titles[item.id]||item.title:'Report unavailable'
const purposes={O01:'Prepare the annual list of incidents and involved vessels.',O02:'Summarize accidents by type and month.',O09:'Review show cause orders, decisions and case outcomes by office.',O11:'Summarize deaths, missing persons, injuries, rescue and ship consequences.'}
const commonReports=computed(()=>['O01','O02','O11','O09'].map(id=>outputCatalogue.find(item=>item.id===id)))
const reportChoices=computed(()=>outputCatalogue.filter(item=>(group.value==='All'||item.group===group.value)&&`${item.id} ${item.title} ${reportTitle(item)} ${item.group}`.toLowerCase().includes((search.value||'').toLowerCase())))
const reportGroups=computed(()=>groups.value.filter(name=>name!=='All').map(name=>({name,items:reportChoices.value.filter(item=>item.group===name)})).filter(item=>item.items.length))
const activeFilters=computed(()=>Object.entries(selection.value).filter(([,value])=>value!=null&&value!==''&&String(value).toLowerCase()!=='all'))
const moreFilters=ref(false),allReportsOpen=ref(false)
const years=computed(()=>[{label:'All years',value:'All'},...[...new Set(store.visibleEvents.value.filter(e=>e.date&&!e.dateUnknown).map(e=>e.date.slice(0,4)))].sort().reverse().map(value=>({label:value,value}))])
const offices=computed(()=>marinaFilterOptions('aor',store.visibleEvents.value,store.state.offices))
const selectedYear=computed({get:()=>!selection.value.year||String(selection.value.year).toLowerCase()==='all'?'All':String(selection.value.year),set:value=>{selection.value={...selection.value,year:value}}})
const selectedOffice=computed({get:()=>!selection.value.aor||String(selection.value.aor).toLowerCase()==='all'?'All':selection.value.aor,set:value=>{selection.value={...selection.value,aor:value}}})
watch(search,value=>{if(value)allReportsOpen.value=true})
watch(group,value=>{if(value!=='All')allReportsOpen.value=true})
const exportHistory=computed(()=>store.visibleRecords('exports'))
watch(exportHistory,records=>{if(previewJob.value&&!records.some(record=>record.id===previewJob.value.id)){previewJob.value=null;snapshotOpen.value=false}})
const sections=computed(()=>{
 if(!documentOutput.value)return [{title:'Source and counting notes',content:output.value?.notes},{title:'Template status',content:'Structured demonstration. Official paper size, signatory and editable master remain for MARINA confirmation. Form 1A is template-required; no Form 1A document is generated.'}]
 const revision=documentRevisions.value[0];if(!revision)return[]
 const {event:e,report,evidence}=revision
 const type={O16:'1B',O17:'2',O18:'3B'}[output.value.id]||'spot'
 const preparedBy=report?.preparedBy||store.state.users.find(u=>u.id===e.ownerId)?.name
 if(type!=='spot')return buildMAICSections({type,event:e,report,asOf:asOf.value,preparedBy,evidence})
 return buildSpotSections({event:e,report,preparedBy,evidence})
})
function snapshot(){
 const assessment=reportingAssessment.value,quality=reportingAssessmentMetadata(assessment),reportRows=JSON.parse(JSON.stringify(rows.value)).map(row=>({...row,'Reporting Completeness':quality['Reporting Completeness']}))
 return {title:output.value.title,subtitle:`${output.value.id} · ${template.value} · Fictional demonstration · ${quality['Reporting Completeness']}`,rows:reportRows,sections:[...JSON.parse(JSON.stringify(sections.value)),{title:'Data quality notes',content:Object.entries(quality).map(([key,value])=>`${key}: ${value}`).join('\n')}],metadata:{'Output family':output.value.id,'Counting grain':output.value.grain,'Selected events':population.value.length,'Vessel involvements':outputPopulation.value.reduce((sum,event)=>sum+(event.vessels?.length||0),0),'As of':asOf.value,Selection:JSON.stringify(selection.value),Template:template.value,Notes:note.value||output.value.notes,...quality},events:JSON.parse(JSON.stringify(outputPopulation.value))}
}
function svgFor(snap){const values=snap.rows.slice(0,16).map(r=>({label:r.Category || r.Reference || 'Event',value:Number(r.Total??r.Count??r.Events??1)})); const max=Math.max(1,...values.map(r=>r.value)),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));return `<svg xmlns="http://www.w3.org/2000/svg" width="1100" height="${150+values.length*36}" viewBox="0 0 1100 ${150+values.length*36}"><rect width="100%" height="100%" fill="white"/><g font-family="Arial" fill="#1a365d"><text x="24" y="32" font-size="21">${esc(snap.title)}</text><text x="24" y="58" font-size="12">${esc(snap.metadata['Reporting Completeness']||'Fictional demonstration')} · ${esc(snap.metadata['As of'])} · ${esc(snap.metadata['Counting grain'])} · Full table supplied separately</text>${values.map((r,i)=>`<text x="24" y="${100+i*36}" font-size="12">${esc(r.label)}</text><rect x="270" y="${84+i*36}" width="${r.value/max*720}" height="24" fill="#2b6cb0"/><text x="${1000}" y="${100+i*36}" font-size="12">${r.value}</text>`).join('')}</g></svg>`}
const figure=computed(()=>output.value?.id==='O21'?`data:image/svg+xml;charset=utf-8,${encodeURIComponent(svgFor(snapshot()))}`:'')
async function deliver(format,snap,id){
 const filename=`${id || 'snapshot'}-${snap.metadata?.['As of'] || asOf.value}`
 if(format==='CSV')downloadCSV(`${filename}.csv`,snap.rows)
 else if(format==='XLSX')await downloadXLSX(`${filename}.xlsx`,[{name:'Output',rows:snap.rows},{name:'Selection and method',rows:Object.entries(snap.metadata).map(([Field,Value])=>({Field,Value}))},{name:'Narrative sections',rows:snap.sections.map(s=>({Section:s.title,Content:s.content}))}])
 else if(format==='GeoJSON')downloadGeoJSON(`${filename}.geojson`,snap.events,snap.metadata)
 else if(format==='SVG'){const blob=new Blob([svgFor(snap)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${filename}.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
 else printReport(snap)
}
async function generate(format){if(!store.can('export'))return;if(!reportingAssessment.value.ready&&!workingCopyAccepted.value){error.value='Required reporting information is incomplete. Complete the records or explicitly acknowledge an incomplete working copy.';return}if(documentOutput.value&&!population.value.length){error.value='Choose an incident included in the current filters before downloading this report.';return}busy.value=true;error.value='';try{const snap=snapshot();await deliver(format,snap,output.value.id);const record=store.recordExport({name:output.value.title,outputId:output.value.id,format,status:reportingAssessment.value.ready?'ready':'working_copy',selection:{...selection.value,asOf:asOf.value,eventId:eventId.value},snapshot:snap,createdAt:new Date().toISOString(),createdBy:store.currentUser.value.id,revision:exportHistory.value.filter(j=>j.outputId===output.value.id).length+1,notes:note.value});q.notify({type:'positive',message:`Report ready. Revision ${record.revision} saved in Output history.`})}catch(e){error.value=e.message}finally{busy.value=false}}
function authorizedExport(job){const record=store.visibleRecords('exports').find(item=>item.id===job?.id);if(!record||!store.can('export'))throw new Error('This output is unavailable in your current account scope.');return record}
function reopen(job){try{previewJob.value=authorizedExport(job);snapshotOpen.value=true}catch(e){previewJob.value=null;snapshotOpen.value=false;q.notify({type:'negative',message:e.message})}}
async function redownload(job,format){try{const record=authorizedExport(job),snap=record.snapshot;if(!snap?.rows)throw new Error('This older sample job has no retained table. Rebuild its output family to create a complete snapshot.');await deliver(format || record.format,snap,record.outputId)}catch(e){q.notify({type:'negative',message:e.message})}}
const jobColumns=[{name:'name',label:'Report',field:'name',align:'left'},{name:'revision',label:'Revision',field:'revision'},{name:'format',label:'Format',field:'format'},{name:'createdAt',label:'Created',field:r=>r.createdAt?new Date(r.createdAt).toLocaleString():'Unknown'},{name:'status',label:'Status',field:'status'},{name:'action',label:'Open or download',field:'id'}]
</script>
<template>
 <div class="page-wrap reports-page">
  <PageHeader :title="history?'Saved reports':builder?reportTitle(output):'Reports'" :subtitle="history?'Reopen a saved report or download the same records again.':builder?'Choose the records, check the preview, then download your report.':'Prepare a commonly used MARINA report or find another report below.'" eyebrow="Reports"><template #actions><q-btn v-if="builder||history" no-caps outline icon="description" label="Reports" to="/admin/reports" /><q-btn v-if="!history" no-caps outline icon="history" label="Output history" to="/admin/exports" /></template></PageHeader>
  <q-banner v-if="error" rounded class="bg-red-1 text-negative q-mb-md">{{error}}</q-banner>
  <template v-if="!builder&&!history">
   <div v-if="contextEvent" class="help-note q-mb-lg">Selected incident: <strong>{{contextEvent.ref}}</strong>. Spot and MAIC reports will use this incident. Summary reports keep your current record selection.</div>
   <div class="section-heading"><h2 class="section-title">Common MARINA reports</h2><p class="muted">Start with the report you need to prepare.</p></div>
   <div class="common-reports"><div v-for="item in commonReports" :key="item.id" class="panel common-report"><div class="report-icon"><q-icon :name="item.id==='O11'?'medical_services':item.id==='O09'?'gavel':'table_chart'" size="24px" color="primary" /></div><div class="common-report-copy"><h3>{{reportTitle(item)}}</h3><p class="muted">{{purposes[item.id]}}</p><q-btn no-caps color="primary" flat padding="6px 0" label="Prepare report" icon-right="arrow_forward" :to="reportPath(item.id)" /></div></div></div>
   <div class="panel"><div class="row items-start justify-between q-gutter-md"><div><h2 class="section-title">Incident and investigation reports</h2><p class="muted">Open the relevant report for an incident. Saved revisions and their evidence are retained.</p></div></div><div class="q-gutter-sm report-shortcuts"><q-btn no-caps outline color="primary" label="Spot report" :to="reportPath('O15')" /><q-btn no-caps outline color="primary" label="Form 1B · Initial" :to="reportPath('O16')" /><q-btn no-caps outline color="primary" label="Form 2 · Progress" :to="reportPath('O17')" /><q-btn no-caps outline color="primary" label="Form 3B · Final" :to="reportPath('O18')" /></div><StaticSection dense label="Form 1A availability" class="q-mt-sm"><p class="muted q-px-md q-pt-sm">Form 1A requires its source template before a document can be prepared. The report-receipt summary can still show Form 1A records.</p></StaticSection></div>
   <div class="panel all-reports"><div class="section-heading"><h2 class="section-title">Find another report</h2><p class="muted">Search or browse all 22 report types, including office summaries, maps and source checks.</p></div><div class="report-search"><q-input v-model="search" outlined dense clearable label="Search reports" placeholder="For example: homeport, SCO, casualty"><template #prepend><q-icon name="search" /></template></q-input><q-select v-model="group" outlined dense :options="groups" label="Report group" /></div><StaticSection v-model="allReportsOpen" :label="search||group!=='All'?`${reportChoices.length} matching report types`:'All 22 report types'" icon="list_alt" class="q-mt-md"><div v-if="reportGroups.length" class="report-groups"><div v-for="category in reportGroups" :key="category.name"><div class="report-group-name">{{category.name}}</div><q-list separator><q-item v-for="item in category.items" :key="item.id" clickable :to="reportPath(item.id)" :data-output-id="item.id" class="report-choice"><q-item-section><q-item-label>{{reportTitle(item)}}</q-item-label><q-item-label caption>{{item.formats.map(format=>format==='PDF'?'Print / PDF':format).join(' · ')}}</q-item-label></q-item-section><q-item-section side><q-icon name="chevron_right" color="primary" /></q-item-section></q-item></q-list></div></div><div v-else class="empty-state q-pa-lg"><q-icon name="search_off" size="32px" /><p>No reports match. Try another search or choose All report groups.</p><q-btn flat no-caps color="primary" label="Show all reports" @click="search='';group='All'" /></div></StaticSection></div>
  </template>
  <template v-else-if="builder&&output">
   <div class="panel"><div class="step-heading"><span class="step-number">1</span><div><h2 class="section-title">Choose records</h2><p class="muted">Your current selection is kept until you change it.</p></div></div><div class="essential-filters"><q-select v-model="selectedYear" outlined dense emit-value map-options :options="years" label="Occurrence year" /><q-select v-model="selectedOffice" outlined dense emit-value map-options :options="offices" label="Area of responsibility" /><q-input v-model="asOf" outlined dense type="date" stack-label label="Report date cutoff" /><q-select v-if="documentOutput" v-model="eventId" outlined dense emit-value map-options :options="eventChoices" clearable label="Incident" /></div><q-banner v-if="contextExcluded" dense rounded class="bg-amber-1 text-dark q-mt-md">The selected incident is outside the current filters. Use Clear filters or adjust Filters to include it.</q-banner><div v-if="documentOutput&&population[0]" class="selection-note q-mt-sm">Incident: <strong>{{population[0].ref}}</strong><span v-if="documentRevisions[0]?.report"> · Saved revision {{documentRevisions[0].report.revision}} · {{documentRevisions[0].report.status}}</span><span v-else> · No saved revision; preview uses current incident details.</span></div><p v-if="documentOutput&&!eventId" class="selection-note q-mt-sm">Choose an incident to preview its report. No incident is selected automatically.</p><div class="row items-center justify-between q-mt-md"><span class="text-caption muted">{{activeFilters.length?`${activeFilters.length} record filters applied`:'All records in your account scope'}} · Unknown values remain explicit.</span></div><StaticSection v-model="moreFilters" icon="tune" label="Filters and office details" class="advanced-filters"><div class="q-pt-md"><DataFilters v-model="selection" /><div class="form-grid"><q-select v-model="selection.homeport" outlined dense :options="marinaFilterOptions('homeport',store.visibleEvents.value,store.state.offices)" emit-value map-options label="Homeport office" @update:model-value="store.persist()" /><q-select v-model="selection.cpc" outlined dense :options="marinaFilterOptions('cpc',store.visibleEvents.value,store.state.offices)" emit-value map-options label="CPC office" @update:model-value="store.persist()" /><q-select v-model="selection.issuingOffice" outlined dense :options="marinaFilterOptions('issuingOffice',store.visibleEvents.value,store.state.offices)" emit-value map-options label="Actual issuing office" @update:model-value="store.persist()" /></div></div></StaticSection><StaticSection dense label="Report settings and counting notes"><div class="q-pa-md"><div class="form-grid"><q-select v-model="template" outlined dense :options="['Demonstration v1']" label="Template version" /><q-input v-model="note" outlined dense label="Selection / source note" /></div><p class="muted q-mt-md">{{output.notes}}</p><p class="text-caption muted">Counting unit: {{output.grain}} · Reference: {{output.id}} · Cutoff applies to dated report revisions; event and case details use the saved selection when this report is generated.</p><p class="text-caption muted">Reference layouts are for review. Official editable masters and signatures require MARINA confirmation.</p></div></StaticSection></div>
   <div class="panel"><div class="step-heading"><span class="step-number">2</span><div><h2 class="section-title">Preview report</h2><p class="muted">Check the records and any missing information before downloading.</p></div></div><q-banner :class="reportingAssessment.ready?'bg-green-1 text-positive q-mb-md':'bg-orange-1 text-dark q-mb-md'"><strong>{{reportingAssessment.ready?'Required reporting information addressed':'Incomplete Working Copy'}}</strong><div>{{reportingAssessment.unresolved.length}} unresolved required field(s) · {{reportingAssessment.explained.length}} declared unknown / not applicable.</div><div v-if="reportingAssessment.unresolved.length" class="row q-gutter-xs q-mt-sm" style="max-height:160px;overflow:auto"><q-btn v-for="[id,ref] in [...new Map(reportingAssessment.unresolved.filter(item=>item.eventId).map(item=>[item.eventId,item.eventRef||item.eventId]))]" :key="id" flat dense no-caps :label="ref" :to="`/admin/incidents/${id}`"/></div></q-banner><div class="preview-counts"><span><strong>{{population.length}}</strong> events</span><span><strong>{{outputPopulation.reduce((s,e)=>s+(e.vessels?.length||0),0)}}</strong> vessel involvements</span><span><strong>{{rows.length}}</strong> report rows</span></div><div v-if="figure" class="q-mb-md"><img :src="figure" alt="Selected incident type figure with underlying table below" class="figure-preview" /></div><template v-if="documentOutput"><div v-if="!population.length" class="empty-state q-pa-lg">{{eventId?'This incident is outside the current filters. Adjust the year, office or Filters to include it.':'Choose an incident above to preview the report. Downloads become available after you choose.'}}</div><StaticSection v-for="(section,index) in sections" :key="section.title" :label="section.title" :default-opened="index===0" header-class="text-primary"><p class="narrative q-pa-md">{{section.content}}</p></StaticSection></template><StaticSection v-if="documentOutput" label="Report data table" icon="table_chart"><q-table flat :rows="rows.map((r,i)=>({...r,_key:i}))" :columns="columns" row-key="_key" :pagination="{rowsPerPage:10}" :rows-per-page-options="[10,25,50,0]" wrap-cells class="preview-table" /></StaticSection><q-table v-else flat :rows="rows.map((r,i)=>({...r,_key:i}))" :columns="columns" row-key="_key" :pagination="{rowsPerPage:10}" :rows-per-page-options="[10,25,50,0]" wrap-cells class="preview-table"><template #no-data><div class="q-pa-lg full-width">No matching records for this report. Adjust the selection or create the required case or report revision. An empty selection remains explicit.</div></template></q-table><p class="text-caption muted q-mt-md q-mb-none">Downloads include all {{rows.length}} rows across every page. Unknown is different from a recorded zero.</p></div>
   <div class="panel download-panel"><div class="step-heading"><span class="step-number">3</span><div><h2 class="section-title">Download report</h2><p class="muted">Choose a file type. A copy of this selection and its report content will be kept in Output history.</p></div></div><q-checkbox v-if="!reportingAssessment.ready" v-model="workingCopyAccepted" label="I understand this download is an incomplete working copy" class="q-mb-md"/><div class="download-actions"><q-btn v-for="format in output.formats" :key="format" no-caps :outline="format!=='PDF'" color="primary" :icon="format==='PDF'?'print':'download'" :label="format==='PDF'?'Print / Save as PDF':`Download ${format}`" :loading="busy" :disable="(documentOutput&&!population.length)||(!reportingAssessment.ready&&!workingCopyAccepted)" @click="generate(format)" /></div><p class="text-caption muted q-mt-md q-mb-none">Print / Save as PDF opens the browser print view. Reports use fictional demonstration records.</p></div>
  </template>
  <div v-else-if="history" class="panel"><q-table flat :rows="exportHistory" :columns="jobColumns" row-key="id" :pagination="{rowsPerPage:10,sortBy:'createdAt',descending:true}" wrap-cells><template #body-cell-name="props"><q-td :props="props"><q-btn flat no-caps color="primary" :label="props.value" @click="reopen(props.row)" /></q-td></template><template #body-cell-status="props"><q-td :props="props"><StatusBadge :status="props.value" /></q-td></template><template #body-cell-action="props"><q-td :props="props"><div class="row no-wrap q-gutter-xs"><q-btn no-caps outline size="sm" icon="visibility" label="Snapshot" @click="reopen(props.row)" /><q-btn no-caps flat size="sm" icon="download" label="Download again" @click="redownload(props.row)" /></div></q-td></template><template #no-data><div class="empty-state full-width"><q-icon name="description" size="36px" /><h3>No saved reports yet</h3><p>Prepare and download a report to keep its selection and contents here.</p><q-btn no-caps color="primary" label="Prepare a report" to="/admin/reports" /></div></template></q-table><p class="text-caption muted q-mt-md q-mb-none">Saved reports stay in this browser. Download again uses the saved records, even if live incident details have changed.</p></div>
  <div v-else class="panel">This report is unavailable. <router-link to="/admin/reports">Return to Reports</router-link>.</div>
